/* ===== messenger.css ==================================================
  == Styles shared throughout the Messenger application.
  ======================================================================= */

@import url("chrome://messenger/skin/shared/messenger.css");

.folderMenuItem > .menu-icon,
.menuitem-iconic > .menu-icon {
  display: flex;
}

@media not (prefers-contrast) {
  #messengerWindow:not([lwtheme]) {
    background-color: light-dark(var(--color-gray-20), var(--color-gray-90));

    &:-moz-window-inactive {
      background-color: light-dark(var(--color-gray-10), var(--color-gray-90));
    }
  }

  #messengerWindow[lwtheme] {
    background-color: var(--lwt-frame);

    &:-moz-window-inactive {
      background-color: var(--lwt-frame-inactive, var(--lwt-frame));
    }
  }

  /* This is needed for Windows 10, see bug 1963783 */
  #messengerWindow[customtitlebar][sizemode="normal"] {
    border-block-start: 0.5px solid rgba(0, 0, 0, 0.7);

    @media (-moz-windows-accent-color-in-titlebar) or (-moz-windows-mica) {
      border-block-start-color: ActiveBorder;

      &:-moz-window-inactive {
        border-block-start-color: InactiveBorder;
      }
    }
  }

  /* Only apply mica when accent color in titlebar is disabled */
  @media (-moz-windows-mica) and (-moz-windows-accent-color-in-titlebar: 0) {
    #messengerWindow[customtitlebar]:not([lwtheme]) {
      background-color: transparent;

      /* stylelint-disable-next-line media-query-no-invalid */
      @media -moz-pref("widget.windows.mica.toplevel-backdrop", 2) {
        /* For acrylic, do the same we do for popups to guarantee some contrast */
        background-color: light-dark(rgba(255, 255, 255, 0.6), rgba(0, 0, 0, 0.6));
      }
    }
  }
}

@media (prefers-contrast) {
  #messengerWindow[customtitlebar]:not([lwtheme]) {
    padding-block-start: 2px;
    background-color: ActiveCaption;
    color: CaptionText;

    &:-moz-window-inactive {
      background-color: InactiveCaption;
      color: InactiveCaptionText;
    }
